INSERT INTO tensor_maturity_verdicts (repo, scope, mission_id, level, evidence, verdict_by) VALUES ('TensorLBM', 'm20070 GAP-DIFFLBM-BOUNDARY-GRAD', 20151, 2, '{"impl_files": ["docs/board_audit/m20151/delivered_snapshot/src/tensorlbm/diff_boundary_grad.py", "docs/board_audit/m20151/delivered_snapshot/scripts/run_gap_diff_boundary_grad.py"], "entry": "docs/board_audit/m20151/delivered_snapshot/scripts/run_gap_diff_boundary_grad.py", "run_artifacts": ["docs/board_audit/m20151/delivered_snapshot/artifacts/diff_boundary_grad_full.json", "docs/board_audit/m20151/delivered_snapshot/artifacts/diff_boundary_grad_quick.json", "docs/board_audit/m20151/delivered_snapshot/artifacts/fig1_wall_anchors.png", "docs/board_audit/m20151/figures/fig1_ad_vs_fd_matrix.png", "docs/board_audit/m20151/figures/fig2_dfg_cd_fail.png"], "tests": ["tests/test_diff_boundary_grad.py::test_plane_couette_matches_exact_solution", "tests/test_diff_boundary_grad.py::test_plane_poiseuille_matches_exact_solution", "tests/test_diff_boundary_grad.py::test_ad_matches_central_difference[bb_static-0.06-0.001]", "tests/test_diff_boundary_grad.py::test_ad_matches_central_difference[bb_moving-0.06-0.001]", "tests/test_diff_boundary_grad.py::test_ad_matches_central_difference[penalization-12.3-0.01]", "tests/test_diff_boundary_grad.py::test_penalization_geometry_gradient_is_not_detached", "tests/test_diff_boundary_grad.py::test_closure_values_agree_in_magnitude", "AUDIT RE-RUN: 7 passed in 47.55s (docs/board_audit/m20151/evidence/pytest_m20151.log)"], "integration_callers": [], "integration_note": "none: grep -rl --include=*.py -F diff_boundary_grad /root/tensor-ecosystem/TensorLBM -> 0 files; no import of DiffChannel2D outside the deliverable itself; not wired into any main solver or platform API -> L3 not earned", "benchmark": {"tensor_benchmark_cases_rows_for_anchor": 0, "xval_rows_for_anchor": 0, "gradient_claim_ref_vs_got": "AD vs central FD, 3 closures x 2 objectives (drag, lift) x 3 groups x 2 FD steps = 36 comparisons: worst rel err 1.770e-03 (coarse FD step, resolution_scan) / 4.430e-04 (fine FD step); 0 rows over the predeclared 1e-2 gate; 0 degenerate (zero-vs-zero) pairs", "exact_anchor_ref_vs_got": "plane Couette wall force ref 0.002 vs got -0.0020000000001, rel err 3.853e-11; plane Poiseuille per-wall force ref 0.0016 vs got 0.0016000000000, rel err 1.479e-11; profile max rel err 1.182e-11 (Couette) / 2.306e-03 (Poiseuille)", "external_benchmark_ref_vs_got": "DFG 2-D-1 (Re=20, D=8, 35x176) C_D 5.57-5.59 vs got 74.83 -> rel err 1241% FAIL; C_L 0.0108 vs got 9.68e-14; C_D monotone 51.19 -> 104.70 over steps 7000-10000 (no steady state) -> absolute body force unvalidated, honest FAIL disclosed by the subject", "passed": false}, "repro_cmd": "cd <TensorLBM>; PYTHONPATH=src python3 scripts/run_gap_diff_boundary_grad.py --mode full --part anchors --anchor-ny 22 --anchor-steps 10000 --dfg-dcells 8 --dfg-re 20 --dfg-steps 10000 --dfg-sample-from 7000 --grad-steps 300 && PYTHONPATH=src python3 scripts/run_gap_diff_boundary_grad.py --mode full --part grad_main --grad-ny 30 --grad-nx 96 --grad-dcells 8 --grad-steps 200 && PYTHONPATH=src python3 scripts/run_gap_diff_boundary_grad.py --mode full --part grad_coarse --grad-ny 26 --grad-nx 88 --grad-dcells 7 --grad-tau 0.6 --grad-steps 200 && PYTHONPATH=src python3 scripts/run_gap_diff_boundary_grad.py --mode full --part grad_horizon --grad-ny 30 --grad-nx 96 --grad-dcells 8 --grad-steps 200", "repro_verified": "audit re-ran all four documented blocks in independent processes: 18/18 matrix rows and 12 anchor scalars reproduce bit-for-bit (d=0.0e+00) -> docs/board_audit/m20151/evidence/repro_compare.txt, evidence/repro_anchors.txt", "external_anchor": "Batchelor exact plane Couette / plane Poiseuille solutions (Couette force 3.85e-11, Poiseuille momentum balance 1.48e-11); Schafer & Turek 1996 NNFM 48:547-566 DFG ranges 2-D-1 5.57-5.59 and 2-D-2 3.22-3.24 (the delivered run is 2-D-1 and fails)", "landing_gap": "subject deliverables untracked in /root/tp-agent/work/m20070, absent from origin/main, no agent/m20070 branch pushed; evidence pointers here resolve to a sha256-identical audit snapshot (docs/board_audit/m20151/evidence/sha256_source.txt) because the canonical src/tensorlbm/diff_boundary_grad.py is not in main (finding F6)", "landing_gap_canonical_impl": "src/tensorlbm/diff_boundary_grad.py (m20070 work tree, uncommitted)", "findings": {"F1_medium": "DFG section mislabels the executed 2-D-1/Re=20 run as 2-D-2/Re=100 with ref 3.22-3.24; printed 1241.08% is 74.83/5.58 (3.23 gives 2217%); the ''rho_max=nan/u_max=nan'' diagnosis is NOT in the artifact (field_snapshot.ux/uy have 0 NaNs, |u|max 0.467/0.195) -> WITHHELD, FAIL conclusion itself sound", "F2_medium": "stale labels: report s5 says 1200/800 steps and ''second lattice D=8'' vs actual 200/100 steps and D=5.25 (22x73); report s3 appends never-executed anchor rows (34x8/20000; DFG 2-D-2 43x220/Re=100/60000)", "F3_low_medium": "artifact lattice.main (44x140, D=10, u0=0.2) does not describe the gradient_matrix it contains (30x96, D=8, u0=0.25); driver uses payload.setdefault(''lattice'', ...) so the first --part invocation wins", "F4_low": "headline ''worst 1.31e-03 over the whole matrix'' aggregates the fine FD step only; worst over both declared steps is 5.20e-03 (gate 1e-2 still passes by >=1.9x)", "F5_medium": "volume-penalisation force has no external anchor (only a self-comparison against bounce-back, ratios 0.885/1.020/1.222)", "F6_medium": "delivery not landed: untracked files, origin/main absent, 0 benchmark/xval rows for the anchor"}, "level_basis": "L2 = real implementation (DiffChannel2D, 339 lines, 3 closures x 2 force objectives) + entry + run artifacts + verified AD-vs-FD (worst 5.20e-03 <= 1e-2, non-degenerate) + exact channel anchors at 1e-11; L3 denied (0 integration callers), L4 denied (DFG external benchmark FAIL, no registered benchmark row)", "audit_report": "docs/board_audit/m20151/AUDIT.md"}'::jsonb, 'board-